using System;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Freyja.WorldBuilder.Editor;
public static class Smooth023 {public static object Main(){var root=GameObject.Find("Island023");var t=root.GetComponentInChildren<Terrain>();var td=t.terrainData;var method=typeof(Island023).GetMethod("Height",BindingFlags.NonPublic|BindingFlags.Static);var sample=(Func<float,float,List<Island023.Route>,float>)Delegate.CreateDelegate(typeof(Func<float,float,List<Island023.Route>,float>),method);var routes=Island023.Routes();int n=td.heightmapResolution;var h=new float[n,n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z,x]=(sample(x/(float)(n-1)*160-80,z/(float)(n-1)*160-80,routes)+5)/40;td.SetHeights(0,0,h);EditorUtility.SetDirty(td);foreach(Transform p in root.transform.Find("Ruas e caminhos")){if(p.name=="Praça central")continue;var mesh=p.GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices;for(int i=0;i<v.Length;i++)v[i].y=t.SampleHeight(v[i])-5+.055f;mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);}int k=0;foreach(Transform p in root.transform.Find("Pedras e árvores editáveis")){var pos=p.position;pos.y=t.SampleHeight(pos)-5;if(p.name.StartsWith("Rock")){p.localScale=new Vector3(3.2f+(k%3)*.25f,2.1f+(k%5)*.2f,3.6f);pos.y-=.5f;}p.position=pos;k++;}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.scene);return "Encostas suavizadas";}}
